<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { api } from '../api/client'
import { useGameStore } from '../stores/game'
const store=useGameStore();const newName=ref('');const importText=ref('');const localError=ref('');const message=ref('');const deleteId=ref<number|null>(null);const exportBusy=ref(false)
onMounted(()=>{void store.loadSaves()})
function date(value:string){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function create(){if(!newName.value.trim())return;await store.createSave(newName.value.trim());if(!store.error)newName.value=''}
async function remove(id:number){await store.deleteSave(id);if(!store.error)deleteId.value=null}
async function exportOne(id:number){localError.value='';exportBusy.value=true;try{const data=await api.exportSave(id);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`宗门存档-${id}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='存档已导出，请保管好备份文件。'}catch(error){localError.value=error instanceof Error?error.message:'导出失败，请重试'}finally{exportBusy.value=false}}
async function importOne(){localError.value='';try{const payload:unknown=JSON.parse(importText.value);await store.importSave(payload);if(!store.error){importText.value='';message.value='存档已导入，并切换至新存档。'}}catch{localError.value='存档内容无法解析，请确认粘贴了完整的 JSON 文件。'}}
async function readFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{importText.value=await file.text();localError.value=''}catch{localError.value='无法读取文件，请重试'}input.value=''}
</script>
<template><p class="muted">各存档独立经营，切换时会结算该档离线收益。</p><div v-if="localError" class="error-box" role="alert">{{ localError }}</div><div v-if="message" class="notice-box" role="status">{{ message }}</div><div class="save-list"><article v-for="save in store.saves" :key="save.slot_id" class="save-row" :class="{active:save.slot_id===store.slotId}"><div class="save-name"><strong>{{ save.name }}</strong><span v-if="save.slot_id===store.slotId" class="badge">当前宗门</span><small>最近打理 · {{ date(save.updated_at) }}</small></div><div class="save-actions"><button class="btn btn-small" :disabled="store.busy||save.slot_id===store.slotId" @click="store.switchSave(save.slot_id)">{{ save.slot_id===store.slotId?'当前':'进入' }}</button><button class="btn btn-small" :disabled="store.busy" @click="store.duplicateSave(save.slot_id,`${save.name} 副本`)">复制</button><button class="btn btn-small" :disabled="store.busy||exportBusy" @click="exportOne(save.slot_id)">导出</button><button class="btn btn-small btn-quiet delete-button" :disabled="store.busy" @click="deleteId=save.slot_id">删除</button></div><div v-if="deleteId===save.slot_id" class="delete-confirm" role="alert"><p>确认删除「{{ save.name }}」？删除后无法恢复，建议先导出备份。</p><div><button class="btn btn-small" @click="deleteId=null">保留存档</button><button class="btn btn-small btn-danger" :disabled="store.busy" @click="remove(save.slot_id)">确认删除</button></div></div></article></div><form class="create-save" @submit.prevent="create"><label class="field-label" for="new-save-name">新立宗门</label><div><input id="new-save-name" v-model="newName" maxlength="60" placeholder="为新存档取一个名字" /><button class="btn btn-primary" :disabled="store.busy||!newName.trim()">新建存档</button></div></form><details class="import-save"><summary>从备份导入</summary><div><label class="field-label" for="save-file">选择存档文件</label><input id="save-file" type="file" accept=".json,application/json" @change="readFile" /><label class="field-label" for="import-save-text">或粘贴存档内容</label><textarea id="import-save-text" v-model="importText" rows="4" placeholder="粘贴导出的完整 JSON 内容"></textarea><p class="muted">导入会建立新存档，保留现有宗门。</p><button class="btn" :disabled="store.busy||!importText.trim()" @click="importOne">导入并进入</button></div></details></template>
<style scoped>
.save-list{margin:20px 0}.save-row{display:flex;flex-wrap:wrap;align-items:center;gap:15px;padding:18px 14px;border:1px solid #d3c8ab;background:#f4eedf;margin-bottom:9px}.save-row.active{border-color:#9cad8b;background:#e5ead7}.save-name{flex:1;min-width:150px}.save-name strong{font:17px 'SimSun',serif;margin-right:10px}.save-name>.badge{font-size:9px}.save-name small{display:block;font-size:10px;color:var(--muted);margin-top:6px}.save-actions{display:flex;gap:5px}.delete-button{color:var(--danger)}.delete-confirm{width:100%;padding:12px;background:#f4e5d7;border:1px solid #c7947f}.delete-confirm p{font-size:12px;margin:0 0 10px}.delete-confirm>div{display:flex;gap:8px}.create-save{padding-top:20px;border-top:1px solid var(--border)}.create-save>div{display:flex;gap:9px}.create-save input{flex:1}.import-save{margin-top:24px;border-top:1px solid var(--border);padding-top:18px}.import-save summary{cursor:pointer;color:var(--jade);font-size:13px}.import-save>div{padding-top:16px}.import-save input{width:100%;margin-bottom:16px;font-size:11px}.import-save textarea{font-family:monospace;font-size:11px}.import-save .muted{margin:8px 0 12px}
@media(max-width:640px){.save-row{gap:12px;padding:14px}.save-actions{width:100%;justify-content:space-between}.save-actions .btn{flex:1;font-size:11px}.create-save>div{flex-direction:column}.save-name strong{font-size:17px}}
</style>
